ValidationRule.errorConditionFormula:
OR(
        AND(
        INCLUDES(Lost_Reason__c, "Feature gap"),
        ISNULL(Feature_Gap__c)
        ),
        AND(
        INCLUDES(Lost_Reason__c, "Service gap (example: Visas, Benefits, Time to Hire etc)"),
        ISNULL(Service_Gap__c)
        )
        )
